function [p_g, q_g, i_c_out] = mfun_gfl_power_reference(i_lim_in, u_g, p)
%MFUN_GFL_POWER_REFERENCE Block power_reference of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the Simulink model, which adds its folder to the MATLAB
%   path. The parameters are the fields of the struct p (from the mask, [] as NaN).
i_lim = complex_in(i_lim_in);
[p_g, q_g] = gfl_power_references(i_lim, u_g);
i_c = i_lim;
i_c_out = complex_out(i_c);
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end

function [p_g_ref, q_g_ref] = gfl_power_references(i_c_ref, u_g)
%GFL_POWER_REFERENCES Power references corresponding to the limited current
%   reference i_c_ref (CurrentVectorController.compute_output, after the
%   CurrentLimiter), which are also used for the anti-windup of the DC-bus voltage
%   controller.
s_g_ref = 1.5*u_g*conj(i_c_ref);
p_g_ref = real(s_g_ref);
q_g_ref = imag(s_g_ref);
end
